#!/usr/bin/env node
// Regenerates packages/router/src/setup/vendor/*.ts from pinned upstream
// releases. Run manually and commit the result — the router image never
// fetches these at build or run time (ACA egress is deny-by-default; see
// docs/superpowers/plans/2026-08-01-setup-management-ui.md, "Why assets are
// vendored as TypeScript").
//
// Usage: node scripts/vendor-setup-assets.mjs
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const ASSETS = [
	{
		out: new URL(
			"../packages/router/src/setup/vendor/pico.ts",
			import.meta.url,
		),
		exportName: "PICO_CSS",
		packageName: "@picocss/pico",
		version: "2.1.1",
		url: "https://unpkg.com/@picocss/pico@2.1.1/css/pico.classless.min.css",
	},
	{
		out: new URL(
			"../packages/router/src/setup/vendor/htmx.ts",
			import.meta.url,
		),
		exportName: "HTMX_JS",
		packageName: "htmx.org",
		version: "2.0.10",
		url: "https://unpkg.com/htmx.org@2.0.10/dist/htmx.min.js",
	},
];

/**
 * Strips a trailing `sourceMappingURL` comment (the CSS block-comment form
 * or the JS line-comment form) so no debug reference to an external `.map`
 * file — which the ACA sandbox could never fetch anyway — ships inside the
 * constant.
 */
function stripSourceMappingComment(body) {
	return `${body
		.replace(/\/\*#\s*sourceMappingURL=.*?\*\/\s*$/s, "")
		.replace(/\/\/#\s*sourceMappingURL=.*$/s, "")
		.trimEnd()}\n`;
}

async function fetchAsset(asset) {
	const response = await fetch(asset.url);
	if (!response.ok) {
		throw new Error(
			`Failed to fetch ${asset.url}: ${response.status} ${response.statusText}`,
		);
	}
	return stripSourceMappingComment(await response.text());
}

async function main() {
	for (const asset of ASSETS) {
		const body = await fetchAsset(asset);
		const outPath = fileURLToPath(asset.out);
		const header =
			`// GENERATED by scripts/vendor-setup-assets.mjs — do not edit.\n` +
			`// Source: ${asset.url}\n` +
			`// Package: ${asset.packageName}@${asset.version}\n`;
		writeFileSync(
			outPath,
			`${header}export const ${asset.exportName} = ${JSON.stringify(body)};\n`,
		);
		console.log(`wrote ${outPath} (${body.length} bytes)`);
	}
}

await main();
